import java.util.Collection;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

// SAFE: Forwarding Wrapper using Composition
class InstrumentedSet<E> {
    private final Set<E> set;
    private int addCount = 0;

    public InstrumentedSet(Set<E> set) {
        this.set = set;
    }

    public boolean add(E e) {
        addCount++;
        return set.add(e); // Delegating to encapsulated set
    }

    public boolean addAll(Collection<? extends E> c) {
        addCount += c.size();
        return set.addAll(c); // set.addAll calls set.add, NOT InstrumentedSet.add!
    }

    public int getAddCount() { return addCount; }
    public int size() { return set.size(); }
}

public class SafeWrapperDemo {
    public static void main(String[] args) {
        InstrumentedSet<String> safeSet = new InstrumentedSet<>(new HashSet<>());
        safeSet.addAll(List.of("Alpha", "Beta", "Gamma"));

        System.out.println("Actual set size: " + safeSet.size());
        System.out.println("Add count tracked: " + safeSet.getAddCount());
    }
}

