interface Logger {
    void log(String message);
}

class ConsoleLogger implements Logger {
    public void log(String message) {
        System.out.println("[Log] " + message);
    }
}

// Decorator adds timestamp without inheritance
class TimestampLoggerDecorator implements Logger {
    private final Logger wrappedLogger;

    public TimestampLoggerDecorator(Logger wrappedLogger) {
        this.wrappedLogger = wrappedLogger;
    }

    @Override
    public void log(String message) {
        String timestamped = "[2026-10-03 10:00:00] " + message;
        wrappedLogger.log(timestamped);
    }
}

public class DecoratorDemo {
    public static void main(String[] args) {
        Logger standard = new ConsoleLogger();
        Logger timestamped = new TimestampLoggerDecorator(standard);

        timestamped.log("Server initiated startup routine.");
    }
}

