interface TextPrinter {
    void print(String text);
}

class StandardPrinter implements TextPrinter {
    @Override
    public void print(String text) {
        System.out.println("[Standard] " + text);
    }
}

class UpperCasePrinterDecorator implements TextPrinter {
    private TextPrinter wrappedPrinter;
    public UpperCasePrinterDecorator(TextPrinter wrappedPrinter) {
        this.wrappedPrinter = wrappedPrinter;
    }
    @Override
    public void print(String text) {
        wrappedPrinter.print(text.toUpperCase());
    }
}

public class DecoratorApp {
    public static void main(String[] args) {
        TextPrinter standard = new StandardPrinter();
        TextPrinter upper = new UpperCasePrinterDecorator(standard);
        upper.print("hello world");
    }
}

import java.util.LinkedList;

class BoundedQueue {
    private LinkedList<String> list = new LinkedList<>();
    private int capacity;

    public BoundedQueue(int capacity) {
        this.capacity = capacity;
    }

    public boolean offer(String item) {
        if (list.size() < capacity) {
            list.addLast(item);
            return true;
        }
        return false;
    }

    public String poll() {
        return list.isEmpty() ? null : list.removeFirst();
    }

    public int size() {
        return list.size();
    }
}

public class QueueApp {
    public static void main(String[] args) {
        BoundedQueue q = new BoundedQueue(2);
        System.out.println("Offer A: " + q.offer("Item A"));
        System.out.println("Offer B: " + q.offer("Item B"));
        System.out.println("Offer C: " + q.offer("Item C"));
        System.out.println("Polled: " + q.poll());
    }
}

