class BaseService {
    public void init() {
        System.out.println("Base init");
    }
}

class SubService {
    private String configKey = "SECRET-KEY-99";
    private BaseService base = new BaseService();

    public void init() {
        base.init();
        System.out.println("Config loaded: " + configKey.toUpperCase());
    }
}

public class ConstructorBugApp {
    public static void main(String[] args) {
        SubService service = new SubService();
        service.init();
    }
}

interface MessageChannel {
    String send(String rawMessage);
}

class BasicChannel implements MessageChannel {
    @Override
    public String send(String rawMessage) {
        return "[Raw: " + rawMessage + "]";
    }
}

class EncryptionDecorator implements MessageChannel {
    private MessageChannel next;
    public EncryptionDecorator(MessageChannel next) {
        this.next = next;
    }
    @Override
    public String send(String rawMessage) {
        return "[Encrypted(" + next.send(rawMessage) + ")]";
    }
}

class CompressionDecorator implements MessageChannel {
    private MessageChannel next;
    public CompressionDecorator(MessageChannel next) {
        this.next = next;
    }
    @Override
    public String send(String rawMessage) {
        return "[Compressed(" + next.send(rawMessage) + ")]";
    }
}

public class PipelineApp {
    public static void main(String[] args) {
        MessageChannel basic = new BasicChannel();
        MessageChannel compressed = new CompressionDecorator(basic);
        MessageChannel pipeline = new EncryptionDecorator(compressed);

        System.out.println(pipeline.send("payload_data"));
    }
}
